package com.jinloes.practice;
import java.util.Arrays; import static org.assertj.core.api.Assertions.assertThat;
public final class ExampleRunner { private static final String USAGE="Input: a salary array followed by the target payroll, for example: [90, 30, 100, 40] 210"; private ExampleRunner(){} public static void main(String[] args){ if (args.length > 0) { runInput(String.join(" ", args).trim()); return; } assertThat(Solution.findSalaryCap(new int[]{90,30,100,40},210)).isCloseTo(70.0, org.assertj.core.data.Offset.offset(1.0e-6)); assertThat(Solution.findSalaryCap(new int[]{20,30},100)).isEqualTo(-1.0); assertThat(Solution.findSalaryCap(new int[]{10,20,30},30)).isCloseTo(10.0, org.assertj.core.data.Offset.offset(1.0e-6)); System.out.println("Examples passed: 3"); } private static void runInput(String input){ try{ int end=input.indexOf(']'); if(end<0) throw new IllegalArgumentException(); int[] s=parse(input.substring(0,end+1)); double target=Double.parseDouble(input.substring(end+1).trim()); System.out.println(Solution.findSalaryCap(s,target)); }catch(RuntimeException e){ System.out.println(USAGE); } } static int[] parse(String t){ String c=t.replace('[',' ').replace(']',' ').replace(',',' ').trim(); if(c.isEmpty()) return new int[0]; return Arrays.stream(c.split("\\s+")).mapToInt(Integer::parseInt).toArray(); } }
